import numpy as np, pickle

def rot_align(a,b):
    a=a/np.linalg.norm(a); b=b/np.linalg.norm(b)
    v=np.cross(a,b); c=a@b
    if np.linalg.norm(v)<1e-8: return np.eye(3) if c>0 else -np.eye(3)
    vx=np.array([[0,-v[2],v[1]],[v[2],0,-v[0]],[-v[1],v[0],0]])
    return np.eye(3)+vx+vx@vx*(1/(1+c))
def Ry(t):
    c,s=np.cos(t),np.sin(t); return np.array([[c,0,s],[0,1,0],[-s,0,c]])
def eq(deg,y=0.0,r=1.0):
    t=np.radians(deg); v=np.array([np.cos(t),y,np.sin(t)]); return v/np.linalg.norm(v)*r

mB=pickle.load(open('coreB.pkl','rb'))
symB=[a.GetSymbol() for a in mB.GetAtoms()]
Ir=29; CcB=28; Ca=0; Cb=2
confsB=[]
for c in range(mB.GetNumConformers()):
    p=mB.GetConformer(c).GetPositions(); p=p-p[Ir]
    p=p@rot_align(p[CcB],np.array([0.,1.,0.])).T
    mid=(p[Ca]+p[Cb])/2; tgt=eq(180)
    p=p@Ry(np.arctan2(mid[2],mid[0])-np.arctan2(tgt[2],tgt[0])).T
    confsB.append(p)

frags=pickle.load(open('frags.pkl','rb'))
mA=frags['A']; symA=[a.GetSymbol() for a in mA.GetAtoms()]
for a in mA.GetAtoms():
    if a.GetSymbol()=='C':
        nb=[n.GetSymbol() for n in a.GetNeighbors()]
        if nb.count('N')==2 and len(nb)==2:
            cidx=a.GetIdx(); nn=[n.GetIdx() for n in a.GetNeighbors()]
confsA=[]
for c in range(mA.GetNumConformers()):
    p=mA.GetConformer(c).GetPositions(); p=p-p[cidx]
    lp=-((p[nn[0]]+p[nn[1]])/2); lp/=np.linalg.norm(lp)
    p=p@rot_align(lp,np.array([0.,1.,0.])).T
    confsA.append(p)

E=[]
E.append(('H',eq(90,0.05,1.60)))     # terminal hydride
E.append(('H',eq(270,-0.05,1.60)))   # terminal hydride
E.append(('H',eq(30,0.55,1.80)))     # bridging hydride
Cdp=eq(0,0.12,2.85); E.append(('Cd',Cdp))
u=eq(-8,-0.12); Me=Cdp+u*2.17; E.append(('C',Me))
uu=u/np.linalg.norm(u); a1=np.cross(uu,[0,1.,0]); a1/=np.linalg.norm(a1); a2=np.cross(uu,a1)
for k in range(3):
    th=2*np.pi*k/3
    E.append(('H',Me+(uu*0.36+(a1*np.cos(th)+a2*np.sin(th))*0.93)*1.10))
symE=[e[0] for e in E]; posE=np.array([e[1] for e in E])

def clash(p1,p2,cut=2.7):
    d=np.linalg.norm(p1[:,None,:]-p2[None,:,:],axis=-1)
    return np.sum(np.clip(cut-d,0,None)**2)+8*np.sum(np.clip(2.0-d,0,None)**2)

best=None
for ib,pB in enumerate(confsB):
    s1=clash(pB,posE)
    base=np.vstack([pB,posE])
    for ia,pA0 in enumerate(confsA):
        for deg in range(0,360,5):
            pA=pA0@Ry(np.radians(deg)).T+np.array([0.,-2.08,0.])
            sc=s1+clash(base,pA)
            if best is None or sc<best[0]: best=(sc,ib,ia,deg,s1)
print('best',best)
sc,ib,ia,deg,s1=best
pB=confsB[ib]; pA=confsA[ia]@Ry(np.radians(deg)).T+np.array([0.,-2.08,0.])
sym=list(symB)+symE+symA; pos=np.vstack([pB,posE,pA])
offE=len(symB); offA=offE+len(symE)
info=dict(Ir=Ir,CcB=CcB,Ca=Ca,Cb=Cb,H1=offE,H2=offE+1,Hb=offE+2,Cd=offE+3,Me=offE+4,CcA=offA+cidx,offA=offA)
with open('raw.xyz','w') as f:
    f.write('%d\nassembled\n'%len(sym))
    for s,p in zip(sym,pos): f.write('%-3s %12.6f %12.6f %12.6f\n'%(s,p[0],p[1],p[2]))
pickle.dump(info,open('info.pkl','wb'))
print(info,len(sym))
d=np.linalg.norm(pos[:,None]-pos[None],axis=-1); np.fill_diagonal(d,99)
print('min',d.min())
for i,j in np.argwhere(d<1.7):
    if i<j and abs(i-j)>8 and not (sym[i]=='H' and sym[j] in('C','N') and False): 
        if d[i,j]<1.7 and not (min(i,j)<len(symB) and max(i,j)<len(symB) and False):
            pass
# print only contacts between different groups
def grp(i):
    return 0 if i<offE else (1 if i<offA else 2)
for i,j in np.argwhere(d<2.2):
    if i<j and grp(i)!=grp(j): print('inter',i,sym[i],j,sym[j],round(d[i,j],2))
